'use strict';
const fs=require('fs'),path=require('path'),zlib=require('zlib'),crypto=require('crypto');
const files=JSON.parse(zlib.inflateSync(Buffer.from('','base64')).toString());
for(const f of files){if(!/^SOFIA_APP\//.test(f.path)||f.path.split('/').includes('..'))throw Error('Unsafe path');if(crypto.createHash('sha256').update(f.content).digest('hex')!==f.sha256)throw Error('Invalid source hash');fs.mkdirSync(path.dirname(f.path),{recursive:true});fs.writeFileSync(f.path,f.content);}
console.log('Applied',files.length,'verified files');
